source='https://senior-secondary.scsa.wa.edu.au/__data/assets/pdf_file/0006/1232466/Applied-Information-Technology-ATAR-Year-11-Syllabus-for-teaching-from-2026.PDF'
bridges={}
def bridge(key,title,chapter,section,models,task,checks,reason):
 bridges[key]=dict(title=title,chapter=chapter,section=section,models=models,task=task,checks=checks,reason=reason)
bridge('elements','Explain every element through a design choice','u1-elements','describe-before-you-judge',[
 ['Line','A thin rule separates event information from the action panel; its direction guides attention.'],['Shape','A circular repair icon categorises the activity without pretending to show depth.'],['Space','A clear margin around the venue prevents collision with the illustration.'],['Texture','A subtle paper pattern suggests a handmade context; keep it out of small text.'],['Colour','Green identifies the event theme; add text labels so colour is not the only cue.'],['3D form','A shaded sphere suggests volume through highlight and shadow; an unshaded circle primarily shows shape.'],['Tone','Dark text against a pale panel creates a light–dark difference independent of hue.']],
 'Create seven small annotated variants of the supplied poster or your own original design, each changing one named element. Compare the result at the intended phone size; keep content constant so the changed element can be discussed.',
 ['Name all seven elements and locate each in the actual output.','Explain one intended effect and one possible readability cost for each change.','Distinguish 2D shape, apparent volume, colour and light–dark tone.'],
 'The earlier worked example concentrated on a date panel; this model makes the less-prominent texture, form and tone distinctions explicit.')
bridge('principles','Connect elements to all six organising principles','u1-principles','visual-weight-and-balance',[
 ['Balance','A large illustration on the left is counterbalanced by the dark information panel on the right; equal column widths are unnecessary.'],['Emphasis: contrast and proportion','Increase the date relative to supporting text and give it a stronger light–dark difference; explain both size relationship and contrast.'],['Dominance','The event heading has the greatest prominence across the composition; the date is emphasised but secondary.'],['Unity: proximity and repetition','Keep date and venue close, and repeat the same label treatment; grouping and repeated treatment provide different links.'],['Pattern','Repeat a small geometric motif at regular intervals in the border; keep it distinct from meaningful content groups.'],['Movement','Heading position, divider direction and grouped details guide the viewing sequence toward the action; no animation is needed.']],
 'First identify and explain these principles in the supplied original poster. Then make two layouts using identical content. Change visual weight and dominance, and annotate contrast, proportion, proximity, repetition, pattern and viewing sequence. Ask a partner to locate the venue without pointing; revise one issue.',
 ['Connect each principle to a visible element and a client need.','Do not equate balance with symmetry or movement with animation.','Keep intended effects separate from the partner observation.'],
 'Adds a single comparison covering every principle, including the parenthetical contrast/proportion and proximity/repetition details.')
bridge('typography','Make type and composition decisions measurable','u1-typography','typography-communicates-structure',[
 ['Typeface','Use one readable sans-serif family for practical details; a different family needs a communication reason.'],['Size','Set heading 40, details 22 and supporting copy 18 in the editable example; test the delivered size rather than treating these values as universal.'],['Alignment','Align date and venue to a shared left edge at x=64; inspect accidental near-alignments.'],['Format','Use bold on labels and regular body copy to distinguish roles; excessive bolding removes that difference.'],['Spacing','Keep a larger gap between information groups than within a date/venue group.'],['Reading gravity','For this English-language poster, trial a top-to-bottom/left-to-right path; imagery, script direction and audience can change it.'],['Thirds','In a 900 × 600 layout, thirds lie at x=300/600 and y=200/400; explore a focal point there, then justify any alternative.'],['Grid and alignment','Use a 64-pixel margin and shared edges; grid guides are planning aids, not mandatory visible artwork.']],
 'Open the editable poster. Create a phone-viewed version and a noticeboard version. Annotate typeface, size, alignment, formatting, spacing, reading path, thirds and grid. Explain which decisions transfer and which need a new output-size test.',
 ['Record numeric positions/sizes where useful and explain their purpose.','Create accurate layouts rather than only describing a proposed design.','Retest the date, venue and next action at the intended viewing size.'],
 'Makes the composition and typography sub-items traceable through numeric design choices and an independent output task.')
bridge('hardware','Follow a task through components and operating systems','u1-hardware','the-operating-system-supports-the-work',[
 ['Components and CPU','Microphone supplies input; CPU executes editing instructions; RAM holds active work; headphones provide output; SSD retains the saved project. A CPU is not the whole computer.'],['Memory purpose and types','RAM is normally volatile primary memory; ROM can hold firmware without power; SSD/HDD/USB are secondary storage. Saving and extra RAM solve different problems.'],['Peripherals','Choose microphone/headphones for recording, scanner for paper input and printer for physical output; verify connection and software support.'],['System categories','A desktop suits the fixed editing desk, a mobile device supports field capture and a server provides shared services. A category alone does not prove compatibility.'],['Named OS examples','Windows, macOS (syllabus: Mac OS) and Linux can support desktop work; iOS and Android are mobile examples. iPadOS is a modern clarification, not a replacement for the named iOS requirement.'],['Four OS functions','The interface accepts a save command; CPU/memory scheduling manages resources; file permissions manage access; process support allows the editor to run. These are OS functions, not the editor’s audio effects.'],['Older software on newer hardware','An old editor requires an unsupported OS/API. Faster hardware does not repair that compatibility failure.'],['New software on older hardware','A new editor requires 8 GB RAM and supported OS X; a fictional older machine has 4 GB and an unsupported OS. Storage capacity cannot satisfy either failure.'],['Selection criteria','Check the exact version’s OS, processor, RAM, free storage and peripheral requirements first, then test recording/export with a representative file. Unknown requirements remain unknown.']],
 'Prepare a selection table for a fictional recording task. Trace input/CPU/memory/output/storage, assign a peripheral by function, compare desktop/mobile/server roles, name all five syllabus OS examples and explain the four OS functions. Test two supplied compatibility scenarios before recommending a system.',
 ['Show a requirement → device evidence → pass/fail/unknown → task test chain.','Explain both directions of older/newer compatibility.','A supported minimum is not a performance guarantee.'],
 'The chapter already explains components; this bridge supplies one joined model for all named OS examples/functions and both compatibility directions.')
bridge('rights','Separate permission, exceptions, authorship and a reference','u1-impacts','keep-a-source-log',[
 ['Copyright purpose','Check control of the proposed reproduction/publication of a protected image; merely finding it online does not authorise reuse.'],['Fair dealing','Research/study and criticism/review are specified purposes with conditions; a public promotion is not automatically permitted because it began as school work.'],['Private use','A lawful personal-use copy and a public upload are different uses; private copying provisions have limited conditions. Do not treat private use as blanket permission.'],['Moral rights','Keep creator credit accurate, avoid false attribution and consider integrity; copyright ownership and creator rights are not identical.'],['Reference and IP acknowledgement','Fictional model: Mo Example, Repair icon, supplied class asset, permission for classroom mock-up only, accessed 27 October 2026, cropped. This is a model record, not a real licence. Include source/terms and required credit in the output, not only a private log.']],
 'For three supplied/original mock assets, record creator, title/description, source, rights holder where different, permission/licence and version, access date, intended use and changes. Place an accurate credit on the draft publication. Explain why a study-note use cannot automatically justify a public campaign use.',
 ['Check permitted use and acknowledgement separately.','Record unclear terms as requiring clarification or replacement.','Use the required referencing style consistently; the model is not a universal style guide.'],
 'Adds explicit contrasting use decisions and a publication credit, rather than mapping every rights item to one general permission story.')
bridge('communication','Choose a community and protect participation','u1-impacts','compare-ways-people-connect',[
 ['Social networking and features','A profile/feed service supports sharing and visible interactions; compare intended audience, persistence, privacy controls and moderation.'],['Online chat room','Real-time text supports quick coordination but decisions can be hard to recover; keep a separate decision summary and agree response windows.'],['Virtual world','Avatars interact in a shared simulated environment; check controls, access requirements, audience and moderation rather than assuming anonymity means safety.'],['Responsible citizenship','Use consent-aware sharing, accurate source credit, respectful messages and agreed boundaries; a private group can still be reshared.'],['Forms of bullying','Fictional threats, impersonation, exclusion and humiliation require a response; do not recreate harmful posts for the task.'],['Limit and respond to harm','Do not amplify it; seek trusted adult support, use appropriate evidence/reporting/blocking guidance and keep intimate-image material out of class evidence.'],['Work–life balance','Agree an ordinary response window such as 4–6 pm on school days with an approved urgent-help route; review whether this excludes team members.']],
 'Compare a moderated forum, chat room, visual feed and virtual world for a fictional group project. Choose one, justify its features and limits, and write a communication agreement with response windows, moderation and a safe route for a fictional harm concern.',
 ['Define the tool’s actual interaction features, not only its brand.','Discuss access, visibility, persistence and time boundaries.','Use invented scenarios and current eSafety guidance.'],
 'Chat rooms were less explicit than virtual worlds in the earlier example; both now have distinct model decisions and practice criteria.')
bridge('formats','Choose every named format for a justified use','u1-applications','compare-graphic-formats',[
 ['CGM','A legacy technical-vector handover requires verified application support. If unsupported, flag it; changing an SVG extension is not conversion.'],['SVG','Use editable paths for a scalable mark; check embedded raster content and target rendering.'],['BMP','A bitmap interchange may be accepted by a legacy tool but is large in this reference set.'],['GIF','Use a palette-based graphic/short animation where appropriate; palette conversion can reduce colour information.'],['JPEG','A compressed photographic delivery copy can trade detail for size; repeated lossy saving can degrade it.'],['TIFF','An imaging workflow can use a suitable TIFF encoding; the extension does not establish resolution or print readiness.'],['PNG','A lossless screen graphic can preserve sharp edges/transparency; it is not automatically smaller than every alternative.'],['MP3','A lossy listening copy requires a listening/player test and retained source.'],['WAV','The supplied PCM master supports editing; WAV is a container and not every WAV uses PCM.'],['WMA','A client’s supported player may accept WMA; test support instead of assuming a browser will play it.'],['Organisation','Keep source/working/exports separate; name versions consistently and retain provenance. A folder scheme does not replace backup.']],
 'Use the measured production workflow to export and inspect a raster and audio delivery copy. Modify the vector mark in an approved editor and check its exported appearance. For each named format, write a suitable/unsuitable client condition, including what to do if CGM support is unknown. Submit a folder plan and actual source/export files.',
 ['Cover all ten named formats in the decision table.','Demonstrate vector, raster and audio use in actual software; do not claim every format was converted.','Record size, relevant settings, rendering/playback and a revision.'],
 'Connects named-format knowledge to individual decisions while distinguishing knowledge of CGM from unperformed conversion.')
bridge('licences','Read licence terms and plan a software change','u1-applications','install-update-and-check-licences',[
 ['Open and closed source','Open-source terms grant defined source-use/modification/redistribution rights; being able to view some source is not sufficient. Closed source does not provide the same rights.'],['Proprietary','An owner-controlled licence can restrict copying/use; it is not a synonym for paid software.'],['Shareware','A trial allows specified evaluation, perhaps with time/features limited; check what happens after that period.'],['Freeware','No purchase price does not imply source access or unrestricted redistribution. These labels can overlap.'],['Installation','For a fictional editor requiring an unsupported OS, pause. Check exact version requirements, official source, school approval and recoverable work before installation.'],['Update','A new version may change file support or plugins. Preserve an editable copy, test representative imports/exports and record the version and outcome.']],
 'Compare four invented licence notices: source modification/redistribution allowed subject to terms; no-price binary with copying restrictions; 14-day trial; paid classroom licence. Classify overlapping labels and list two questions to confirm. Write an installation/update go/no-go checklist for a fictional unsupported OS and plugin dependency; no installation is required.',
 ['Base each classification on rights, price and conditions separately.','Explain both installation and updating, including compatibility and recovery.','A plan demonstrates this knowledge requirement; it is not a claim an installer was run.'],
 'Earlier licence text was mainly explanatory; the contrasting notices and change decision supply a specific worked comparison and independent reasoning task.')
bridge('spreadsheet','Trace, lay out, sort and filter the editable table','u1-applications','test-missing-values-and-protect-relationships',[
 ['VLOOKUP','With P01/Poster/12, A02/Audio/8, V03/Video/30 in A2:C4, =VLOOKUP("A02",$A$2:$C$4,3,FALSE) returns 8. The return index counts within the range.'],['HLOOKUP','With P01/A02/V03 in B1:D1 and 12/8/30 below, =HLOOKUP("A02",$B$1:$D$2,2,FALSE) returns 8. The selected range’s first row holds the keys.'],['Data and layout','Use one record per row, a unique key, labelled columns/units and readable number formats. Preserve the original before sorting.'],['Sort and filter','Move complete related records when sorting. Filtering hides records rather than deleting them; verify the remaining and restored views.'],['Test cases','Known, missing, duplicate, blank, spaced and zero cases need distinct interpretations. Do not replace every missing-key error with zero.']],
 'Complete the linked editable lookup workbook, including both formula directions, independent blank result cells, complete-record sorting, a filtered view and clear-filter check. Keep formulas and predicted/observed results. Explain a layout change and demonstrate recalculation after changing a source value.',
 ['Use the actual workbook coordinates; they differ from this small chapter example.','Submit an editable spreadsheet, not only hand tracing.','Keep missing, duplicate and real-zero cases distinct.'],
 'Existing workbook already supplies operational examples; this bridge explicitly connects layout/data organisation and both knowledge/skill requirements.')
bridge('planning','Build, represent and evaluate a client solution','u1-projects','choose-a-representation-that-answers-your-question',[
 ['Purpose and criteria','Help residents decide to attend; check whether date, venue and next action can be located at the intended output size.'],['Audience','Consider residents’ reading, access and viewing contexts; the client and audience are not automatically the same people.'],['Medium','A phone image and noticeboard print need different size/rendering checks.'],['Situation analysis','The previous notice hides the venue; identify the evidence, constraints and missing information before proposing changes.'],['Style guide','Record heading/body treatments, colour roles, spacing, alignment and image treatment with reasons.'],['Storyboard','Three panels show the sequence: event → what to bring → venue/time, with narration and timing notes.'],['Thumbnails','Two small layouts compare arrangement and hierarchy before detailed production.'],['Wireframe/sketch','A labelled structure locates heading, details, action and return route if interactive; a static poster does not need invented controls.'],['Evaluation','For each criterion, record the actual observation, revision, retest and limitation. An attractive output does not prove the venue task works.']],
 'Produce a short client brief, situation analysis, audience/medium decision, criteria table and style guide. Sketch two thumbnails, storyboard the three-scene version and wireframe an optional linked page. Build one appropriate digital output with annotations covering elements/principles, typography, composition, thirds and grid/alignment. Test the brief’s tasks, revise and evaluate with evidence.',
 ['Retain representations with different purposes; hand/digital sketches are both acceptable.','Apply the design process to an actual output rather than stopping at a plan.','Record every evaluation criterion separately and identify untested claims.'],
 'The earlier task allowed choosing a representation; the new task gives practice in all three named plan components without adding a second assessed project.')

rows=[]
def add(area,kind,page,number,label,key,children=()):
 path=f'{kind[0]}{number}';base=f'U1-{area.upper()}-{path}'
 def entry(id,path,label,parent='',context=False):
  b=bridges[key];rows.append(dict(id=id,area=area,kind=kind,page=page,locator=f'{area} / {kind} / {path}',summary=label,parent=parent,context=context,explanation=f'../../index.html#topic/{b["chapter"]}/{b["section"]}',worked=f'{key}.html#worked',practice=f'{key}.html#independent',evidence=f'{key}.html#checks',status='Parent context: review child rows' if context else 'Authored task/model located; performance unverified' if kind=='Skills' else 'Authored explanation/model/task located; review pending',limitation='Independent subject review remains pending.'+(' Actual learner application/output and observation remain unverified.' if kind=='Skills' else '')))
 entry(base,path,label,context=bool(children))
 for i,child in enumerate(children,1):
  if isinstance(child,tuple):
   name,detail=child;pid=f'{base}.{i}';entry(pid,f'{path}.{i}',name,base,True)
   for j,leaf in enumerate(detail,1):entry(f'{pid}.{j}',f'{path}.{i}.{j}',leaf,pid)
  else:entry(f'{base}.{i}',f'{path}.{i}',child,base)

